/**
 * Department Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. Request payloads and the query object stay local and are marked as
 * such.
 */

import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** The row on GET/POST/PATCH `/departments/:departmentId` (`DepartmentResponseDto`). */
type DepartmentWire = Schemas["DepartmentResponseDto"]
/** A list row: the same row plus its active categories and a computed count. */
type DepartmentListWire = Schemas["DepartmentListItemResponseDto"]

/**
 * Dashboard-facing department.
 *
 * `nameEn` is nullable on the wire but every department surface renders it as a
 * string, so `toDepartment` (`lib/api/departments.ts`) normalises `null` to `""`
 * once. `categories` and `bookableCategoriesCount` only exist on the list row,
 * so they stay optional for the detail/create/update payloads.
 *
 * The old hand-written `_count?: { categories: number }` was removed: no
 * department endpoint sends `_count` (the list handler destructures it away and
 * computes `bookableCategoriesCount` itself), so it was always `undefined` and
 * every reader already fell through to `categories.length`.
 */
export type Department = Omit<DepartmentWire, "nameEn"> & {
  nameEn: string
  categories?: DepartmentListWire["categories"]
  bookableCategoriesCount?: number
}

/* ─── Query (local; not a response shape) ─── */

export interface DepartmentListQuery {
  page?: number
  limit?: number
  search?: string
  isActive?: boolean
}

/* ─── Request payloads (local; validated by the backend DTOs) ─── */

export interface CreateDepartmentPayload {
  nameAr: string
  nameEn: string
  descriptionAr?: string
  descriptionEn?: string
  icon?: string
  sortOrder?: number
  isActive?: boolean
  isVisible?: boolean
}

export interface UpdateDepartmentPayload {
  nameAr?: string
  nameEn?: string
  descriptionAr?: string | null
  descriptionEn?: string | null
  icon?: string | null
  sortOrder?: number
  isActive?: boolean
  isVisible?: boolean
}
